            Exercise(
                name: "Bradford/Rocky Presses",
                details: "",
                category: .strength,
                trackingType: .repsWeight,
                primaryMuscleGroups: [.shoulders, ],
                secondaryMuscleGroups: [.triceps, ],
                iconSystemName: "barbell.figure.strength.exercise",
                isBuiltIn: true,
                createdAt: .now,
                images: ["Bradford_Rocky_Presses/0.jpg", "Bradford_Rocky_Presses/1.jpg"],
                instructions: ["Setzen Sie sich auf eine Militärpressebank mit einer Bar auf Schulterebene mit einem pronierten Griff (Palmen nach vorne). Tipp: Ihr Griff sollte breiter sein als Schulterbreite und es sollte einen 90-Grad Winkel zwischen dem Vorderarm und dem oberen Arm, wie die Hantel geht nach unten. Das ist Ihre Ausgangsposition.", "Sobald Sie die Hantel mit dem richtigen Griff abholen, heben Sie die Stange über den Kopf, indem Sie Ihre Arme verriegeln.", "Jetzt senken Sie die Bar auf die Rückseite des Kopfes langsam, wenn Sie einatmen.", "Heben Sie die Stange wieder in die Ausgangsposition, während Sie ausatmen.", "Senken Sie die Bar langsam in die Ausgangsposition, wenn Sie einatmen. Das ist eine Wiederholung.", "Ändern Sie auf diese Weise, bis Sie die empfohlene Menge an Wiederholungen abschließen."],
            ),
            Exercise(
                name: "Butt-Ups",
                details: "",
                category: .strength,
                trackingType: .reps,
                primaryMuscleGroups: [.core, ],
                secondaryMuscleGroups: [],
                iconSystemName: "figure.core.training",
                isBuiltIn: true,
                createdAt: .now,
                images: ["Butt-Ups/0.jpg", "Butt-Ups/1.jpg"],
                instructions: ["Beginnen Sie eine Push-up-Position, aber mit Ihren Ellbogen auf dem Boden und auf Ihren Unterarmen ruhen. Ihre Arme sollten in einem 90 Grad Winkel gebogen werden.", "Bogen Sie Ihren Rücken etwas aus, anstatt Ihren Rücken ganz gerade zu halten.", "Steigern Sie Ihre Gluten in Richtung der Decke, quetschen Sie Ihre Abs fest, um den Abstand zwischen Ihrem Brustkorb und Hüften zu schließen. Das Endergebnis wird sein, dass Sie in einer hohen Brückenposition enden. Ausatmen, wie Sie diesen Teil der Bewegung ausführen.", "Zurück nach unten langsam in Ihre Ausgangsposition, während Sie einatmen. Tipp: Lass deinen Rücken nicht nach unten durchhängen.", "Wiederholen für die empfohlene Menge an Wiederholungen."],
            ),
            Exercise(
                name: "Butt Lift (Bridge)",
                details: "",
                category: .strength,
                trackingType: .reps,
                primaryMuscleGroups: [.glutes, ],
                secondaryMuscleGroups: [.hamstrings, ],
                iconSystemName: "gluteus.bridge",
                isBuiltIn: true,
                createdAt: .now,
                images: ["Butt_Lift_Bridge/0.jpg", "Butt_Lift_Bridge/1.jpg"],
                instructions: ["Legen Sie flach auf dem Boden auf dem Rücken mit den Händen an der Seite und Ihre Knie gebogen. Ihre Füße sollten um die Schulterbreite gelegt werden. Dies wird Ihre Ausgangsposition.", "Schieben vor allem mit den Fersen, heben Sie Ihre Hüften vom Boden, während Sie Ihren Rücken gerade halten. Atmen Sie aus, wie Sie diesen Teil der Bewegung ausführen und halten Sie oben für eine Sekunde.", "Gehen Sie langsam zurück in die Ausgangsposition, während Sie einatmen."],
