            Exercise(
                name: "Dumbbell Clean",
                details: "",
                category: .strength,
                trackingType: .repsWeight,
                primaryMuscleGroups: [.hamstrings, ],
                secondaryMuscleGroups: [.calves, .forearms, .glutes, .lowerBack, .quads, .shoulders, .traps, ],
                iconSystemName: "dumbbell.clean",
                isBuiltIn: true,
                createdAt: .now,
                images: ["Dumbbell_Clean/0.jpg", "Dumbbell_Clean/1.jpg"],
                instructions: ["Beginnen Sie mit einer Hantel in jeder Hand mit Ihrer Fußschulterbreite auseinander.", "Untere die Gewichte auf den Boden, indem du an den Hüften und Knien biegest und deine Hüften zurückschiebst, bis die Hanteln den Boden erreichen. Dies wird Ihre Ausgangsposition.", "Um die Bewegung zu initiieren, springen gewaltsam nach oben, indem die Hüften, Knie und Knöchel, um die Gewichte nach oben zu beschleunigen. Halten Sie einen neutralen Griff auf den Hanteln, halten Sie die Arme gerade, bis die volle Verlängerung erreicht ist.", "Nach der vollen Verlängerung, beugte die Hüften und Knie, um das Gewicht in einer Sitzposition zu erhalten. Erlauben Sie den Armen zu biegen, die Hanteln zu Ihren Schultern zu führen.", "Wenn Sie das Gewicht in der Hocketposition erhalten, verlängern Sie die Hüften und Knie, um in einer Stehposition mit den Gewichten auf den Schultern zu beenden."],
            ),
            Exercise(
                name: "Dumbbell Floor Press",
                details: "",
                category: .other,
                trackingType: .repsWeight,
                primaryMuscleGroups: [.triceps, ],
                secondaryMuscleGroups: [.chest, .shoulders, ],
                iconSystemName: "dumbbell.press",
                isBuiltIn: true,
                createdAt: .now,
                images: ["Dumbbell_Floor_Press/0.jpg", "Dumbbell_Floor_Press/1.jpg"],
                instructions: ["Lay auf dem Boden hält Hanteln in den Händen. Ihre Knie können gebogen werden. Beginnen Sie mit den Gewichten voll über Sie erweitert.", "Senken Sie die Gewichte, bis Ihr Oberarm in Kontakt mit dem Boden kommt. Sie können Ihre Ellenbogen zu betonen Trizps Größe und Stärke, oder auf Ihre Brust Winkel Ihre Arme zur Seite zu konzentrieren.", "Halten Sie nach unten und bringen Sie dann das Gewicht nach oben durch die Ellbogen."],
