            Exercise(
                name: "Vertical Swing",
                details: "",
                category: .plyometrics,
                trackingType: .reps,
                primaryMuscleGroups: [.hamstrings, ],
                secondaryMuscleGroups: [.glutes, .quads, .shoulders, ],
                iconSystemName: "figure.strengthtraining.traditional",
                isBuiltIn: true,
                createdAt: .now,
                images: ["Vertical_Swing/0.jpg", "Vertical_Swing/1.jpg"],
                instructions: ["Erlauben Sie der Hantel auf Armlänge zwischen Ihren Beinen zu hängen, sie mit beiden Händen halten. Halten Sie den Rücken gerade und den Kopf hoch.", "Drehen Sie die Hantel zwischen Ihren Beinen, Biegen an den Hüften und Biegen der Knie leicht.", "Kraftvoll die Bewegung umkehren, indem sie sich an den Hüften, Knien und Knöcheln ausbreitet, um sich nach oben zu treiben und die Hantel über den Kopf zu schwingen.", "Wenn Sie landen, absorbieren Sie die Wirkung durch Ihre Beine und ziehen Sie die Hantel zu Ihrem Rumpf vor der nächsten Wiederholung."],
            ),
            Exercise(
                name: "Walking, Treadmill",
                details: "",
                category: .cardio,
                trackingType: .distanceDuration,
                primaryMuscleGroups: [.quads, ],
                secondaryMuscleGroups: [.calves, .glutes, .hamstrings, ],
                iconSystemName: "figure.core.training",
                isBuiltIn: true,
                createdAt: .now,
                images: ["Walking_Treadmill/0.jpg", "Walking_Treadmill/1.jpg"],
                instructions: ["Gehen Sie zunächst auf das Laufband und wählen Sie die gewünschte Option aus dem Menü. Die meisten Laufbänder haben eine manuelle Einstellung, oder Sie können ein Programm zum Laufen auswählen. In der Regel können Sie Ihr Alter und Gewicht eingeben, um die Menge der Kalorien während der Bewegung verbrannt zu schätzen. Die Höhe kann angepasst werden, um die Intensität des Trainings zu ändern.", "Laufbänder bieten Komfort, Herz-Kreislauf-Vorteile und haben in der Regel weniger Auswirkungen als draußen zu gehen. Wenn Sie zu Fuß gehen, sollten Sie sich in einem moderaten bis schnellen Tempo bewegen, nicht eine gemütliche. Als eine Aktivität von geringerer Intensität, wandeln nicht so viele Kalorien wie einige andere Aktivitäten, aber immer noch bietet großen Nutzen. Eine 150 lb Person wird ca. 175 Kalorien zu Fuß 4 Meilen pro Stunde für 30 Minuten verbrennen, verglichen mit 450 Kalorien zweimal so schnell. Halten Sie die richtige Haltung, während Sie gehen, und halten Sie nur auf die Griffe, wenn nötig, wie zum Beispiel bei der Demontage oder Überprüfung Ihrer Herzfrequenz."],
            ),
            Exercise(
                name: "Weighted Ball Hyperextension",
                details: "",
                category: .strength,
                trackingType: .repsWeight,
                primaryMuscleGroups: [.lowerBack, ],
                secondaryMuscleGroups: [.glutes, .hamstrings, .midBack, ],
                iconSystemName: "figure.strengthtraining.traditional",
                isBuiltIn: true,
                createdAt: .now,
                images: ["Weighted_Ball_Hyperextension/0.jpg", "Weighted_Ball_Hyperextension/1.jpg"],
                instructions: ["Um zu beginnen, liegen Sie auf einem Übungsball mit Ihrem Torso drücken gegen den Ball und parallel zum Boden. Der Ball Ihrer Füße sollte gegen den Boden gedrückt werden, um Sie ausgewogen zu halten. Legen Sie eine gewichtete Platte unter Ihrem Kinn oder hinter Ihrem Hals. Dies ist die Ausgangsposition.", "Erhöhen Sie langsam Ihren Rumpf durch Biegen an der Taille und unteren Rücken. Denken Sie daran, während dieser Bewegung auszuatmen.", "Halten Sie die Kontraktion auf Ihrem unteren Rücken für eine Sekunde und senken Sie Ihren Rumpf zurück in die Ausgangsposition beim Einatmen.", "Wiederholen für die empfohlene Menge an Wiederholungen in Ihrem Programm vorgeschrieben."],
            ),
            Exercise(
                name: "Weighted Ball Side Bend",
                details: "",
                category: .strength,
                trackingType: .repsWeight,
                primaryMuscleGroups: [.core, ],
                secondaryMuscleGroups: [],
                iconSystemName: "figure.core.training",
                isBuiltIn: true,
                createdAt: .now,
                images: ["Weighted_Ball_Side_Bend/0.jpg", "Weighted_Ball_Side_Bend/1.jpg"],
                instructions: ["Um zu beginnen, liegen Sie auf einem Übungsball mit der linken Seite des Rumpfes (Wist, Hüften und Schulter) gegen den Ball gedrückt.", "Ihre Füße sollten auf dem Boden sein, während Ihre Beine gekreuzt und hängen vom Ball. Halten Sie eine gewichtete Platte mit der rechten Hand direkt auf der rechten Seite des Kopfes. Tipp: Stellen Sie sicher, dass die glatte Seite der Platte an Ihrem Kopf anliegt.", "Legen Sie Ihren linken Arm über Ihren Rumpf, so dass Ihre Handfläche auf Ihren Schrägen ist. Es sollte einen rechten Winkel zwischen dem linken Unterarm und dem oberen Arm geben. Dies ist die Ausgangsposition.", "Erhöhen Sie die Seite Ihres Rumpfes durch seitliches Biegen an der Taille beim Ausatmen.", "Halten Sie die Kontraktion für eine Sekunde und langsam senken Sie sich zurück in die Ausgangsposition beim Einatmen.", "Wiederholen für die empfohlene Menge an Wiederholungen.", "Schalten Sie Seiten und wiederholen Sie die Übung."],
            ),
            Exercise(
                name: "Weighted Bench Dip",
                details: "",
                category: .strength,
                trackingType: .repsWeight,
                primaryMuscleGroups: [.triceps, ],
                secondaryMuscleGroups: [.chest, .shoulders, ],
                iconSystemName: "figure.strengthtraining.traditional",
                isBuiltIn: true,
                createdAt: .now,
                images: ["Weighted_Bench_Dip/0.jpg", "Weighted_Bench_Dip/1.jpg"],
                instructions: ["Für diese Übung müssen Sie eine Bank hinter Ihrem Rücken und eine andere vor Ihnen setzen. Mit den Bänken senkrecht zu Ihrem Körper, halten Sie an einer Bank an seinem Rand mit den Händen nahe Ihrem Körper, getrennt an Schulterbreite. Ihre Arme sollten vollständig erweitert werden.", "Die Beine werden auf der anderen Bank nach vorne verlängert. Ihre Beine sollten parallel zum Boden sein, während Ihr Rumpf senkrecht zum Boden sein soll. Lassen Sie Ihren Partner die Hantel auf Ihren Schoß legen. Anmerkung: Diese Übung wird am besten mit einem Partner durchgeführt, da die Platzierung des Gewichts auf Ihrem Schoß kann herausfordernd sein und Verletzung ohne Unterstützung verursachen. Dies wird Ihre Ausgangsposition.", "Erniedrigen Sie Ihren Körper, wenn Sie durch Biegen an den Ellbogen einatmen, bis Sie sich weit genug absenken, wo ein Winkel etwas kleiner als 90 Grad zwischen dem Oberarm und dem Unterarm ist. Tipp: Halten Sie die Ellbogen so nah wie möglich während der Bewegung. Unterarme sollten immer nach unten zeigen.", "Mit Ihren Trizeps, um Ihren Rumpf wieder hochzubringen, heben Sie sich beim Ausatmen wieder in die Ausgangsposition.", "Wiederholen für die empfohlene Menge an Wiederholungen."],
            ),
            Exercise(
                name: "Weighted Crunches",
                details: "",
                category: .strength,
                trackingType: .repsWeight,
                primaryMuscleGroups: [.core, ],
